from flask import Flask, render_template
from .services import process_hello, process_test, process_result

app = Flask(__name__)


@app.route('/')
def hello():
    return process_hello()


@app.route('/test')
def test():
    return process_test()


@app.route('/result')
def result():
    result_dict = process_result()
    return render_template('result.html', result=result_dict)
